(5186535, 755400, 52854, '<td valign="top">Precious pup! Love the eyes.</td>', 'Precious pup! Love the eyes.', '2009-01-12 08:52:45.000000', NULL, 1),
(5186538, 755129, 81362, '<td valign="top">Exuberance well-captured. Nice job with exposure in a setting with a challenging dynamic range. Cropping to remove the rear end of the person bending over would help, but leave the leg and arm with gloved hand of the other person so as not to eliminate the element of context. Seven.</td>', 'Exuberance well-captured. Nice job with exposure in a setting with a challenging dynamic range. Cropping to remove the rear end of the person bending over would help, but leave the leg and arm with gloved hand of the other person so as not to eliminate the element of context. Seven.', '2009-01-12 08:54:04.000000', NULL, 1),
(5186541, 755199, 15204, '<td valign="top">What beautiful green eyes, even with tears in them :)  Your color is great.  The image is about a stop underexposed.  For this kind of a close up comp, I would leave a little more space under the chin and take off a little on the top to move the eyes higher in the frame (on the one third line instead of the middle line).  A very nice image.  6 from me.</td>', 'What beautiful green eyes, even with tears in them :)  Your color is great.  The image is about a stop underexposed.  For this kind of a close up comp, I would leave a little more space under the chin and take off a little on the top to move the eyes higher in the frame (on the one third line instead of the middle line).  A very nice image.  6 from me.', '2009-01-12 08:54:33.000000', NULL, 1),
(5186542, 755177, 52854, '<td valign="top">Really nice photo -</td>', 'Really nice photo -', '2009-01-12 08:55:20.000000', NULL, 1),
