(5187279, 754969, 49954, '<td valign="top">Would have preferred seeing this a little tighter on the crap... nice lighting though.</td>', 'Would have preferred seeing this a little tighter on the crap... nice lighting though.', '2009-01-12 14:42:19.000000', NULL, 1),
(5187282, 755158, 49954, '<td valign="top">precious!!!!  Well done.</td>', 'precious!!!!  Well done.', '2009-01-12 14:42:30.000000', NULL, 1),
(5187283, 753768, 75192, '<td valign="top">Wonderful tones and fabulous textures. The rushes add something extra special compositionally to this shot.... the young buck is portrayed excellently here.</td>', 'Wonderful tones and fabulous textures. The rushes add something extra special compositionally to this shot.... the young buck is portrayed excellently here.', '2009-01-12 14:42:41.000000', NULL, 1),
(5187284, 754633, 49954, '<td valign="top">Since they are all dead once off the tree, this DNMC.</td>', 'Since they are all dead once off the tree, this DNMC.', '2009-01-12 14:42:46.000000', NULL, 1),
(5187285, 754801, 15711, '<td valign="top">I saw these when I was at the Nat''l Aquarium this summer and I laugh at their human like "grumpy" expressions.</td>', 'I saw these when I was at the Nat''l Aquarium this summer and I laugh at their human like "grumpy" expressions.', '2009-01-12 14:42:57.000000', NULL, 1),
(5187288, 755043, 15711, '<td valign="top">That''s what we native Texans call "buttermilk sky."  :~)</td>', 'That''s what we native Texans call "buttermilk sky."  :~)', '2009-01-12 14:43:25.000000', NULL, 1),
(5187290, 754005, 55956, '<td valign="top">I would have chosen another point of view, the tree on the upper side is a bit distracting, considering that the challenge run with the advanced editing rules was easy fixed this.</td>', 'I would have chosen another point of view, the tree on the upper side is a bit distracting, considering that the challenge run with the advanced editing rules was easy fixed this.', '2009-01-12 14:43:52.000000', NULL, 1),
(5187291, 755376, 15711, '<td valign="top">I love the soft line of the vase.  Interesting.  I feel as though the crop is too tight though. We need some negative space to the left and bottom.  It feels a bit too crowded to me. :~)</td>', 'I love the soft line of the vase.  Interesting.  I feel as though the crop is too tight though. We need some negative space to the left and bottom.  It feels a bit too crowded to me. :~)', '2009-01-12 14:44:21.000000', NULL, 1),
(5187292, 754147, 15711, '<td valign="top">I know that we are concentrating on the fish, but I''d like to see the men''s faces OR zoom in and just have their hands and knives. :~)</td>', 'I know that we are concentrating on the fish, but I''d like to see the men''s faces OR zoom in and just have their hands and knives. :~)', '2009-01-12 14:44:57.000000', NULL, 1),
(5187297, 755236, 15711, '<td valign="top">This seems over sharpened to me, or maybe adjusted with highlights and shadows.  I can''t tell, but something seems a touch off.  Love the bokeh. :~)</td>', 'This seems over sharpened to me, or maybe adjusted with highlights and shadows.  I can''t tell, but something seems a touch off.  Love the bokeh. :~)', '2009-01-12 14:45:38.000000', NULL, 1),
(5187298, 755364, 67145, '<td valign="top">this is so cool .. a fantastic photograph .. it makes me smile which is always a good thing .. !! .. your title is perfect .. :)</td>', 'this is so cool .. a fantastic photograph .. it makes me smile which is always a good thing .. !! .. your title is perfect .. :)', '2009-01-12 14:45:44.000000', NULL, 1),
(5187301, 755345, 75192, '<td valign="top">Good silhouette picture.... I believe the placement of the rock and the sun give a nice depth to this picture.</td>', 'Good silhouette picture.... I believe the placement of the rock and the sun give a nice depth to this picture.', '2009-01-12 14:46:39.000000', NULL, 1),
(5187308, 755165, 49954, '<td valign="top">Nice effort, but out of focus</td>', 'Nice effort, but out of focus', '2009-01-12 14:48:12.000000', NULL, 1),
(5187309, 754778, 55956, '<td valign="top">nice point of view and colors. I remembering seven lives for a cat....</td>', 'nice point of view and colors. I remembering seven lives for a cat....', '2009-01-12 14:48:23.000000', NULL, 1),
(5187310, 754741, 75192, '<td valign="top">Very cute doggie. I''m a really sucker for these puppies pictures!!! <br/> <br/>The cute look in doggies eyes is adorable and just says "give me a good score...ppp--ppp--ppp---leeeease" and the ear flapped over the arm of the chair is excellent in terms of photographic composition. <br/> <br/>Nice tones, I think it''s a good example of sepia tones and textures.</td>', 'Very cute doggie. I''m a really sucker for these puppies pictures!!!  The cute look in doggies eyes is adorable and just says "give me a good score...ppp--ppp--ppp---leeeease" and the ear flapped over the arm of the chair is excellent in terms of photographic composition.  Nice tones, I think it''s a good example of sepia tones and textures.', '2009-01-12 14:48:27.000000', NULL, 1),
(5187311, 755288, 49954, '<td valign="top">Closer, lack of detail on the person...</td>', 'Closer, lack of detail on the person...', '2009-01-12 14:48:32.000000', NULL, 1),
