(5189035, 755222, 68947, '<td valign="top">Perfect capture!  Love the crop, the framing...the message behind it, the b&amp;w...really has a message and very well executed.  9</td>', 'Perfect capture!  Love the crop, the framing...the message behind it, the b&w...really has a message and very well executed.  9', '2009-01-13 11:42:20.000000', NULL, 1),
