(5189616, 755378, 75192, '<td valign="top">A nice abstract, but a bit too blurry and not enough colour - the green and white don''t seem to carry the shot well enough.</td>', 'A nice abstract, but a bit too blurry and not enough colour - the green and white don''t seem to carry the shot well enough.', '2009-01-13 18:50:16.000000', NULL, 1),
(5189617, 753773, 76598, '<td valign="top">unique splash, I would have liked more DOF</td>', 'unique splash, I would have liked more DOF', '2009-01-13 18:50:26.000000', NULL, 1),
(5189618, 755135, 75192, '<td valign="top">It''s quite a nice shot, but there is no life in it to my eye. I''m quite open minded about these challenges, and I dig your creativity, but it doesn''t really work for me.</td>', 'It''s quite a nice shot, but there is no life in it to my eye. I''m quite open minded about these challenges, and I dig your creativity, but it doesn''t really work for me.', '2009-01-13 18:51:07.000000', NULL, 1),
(5189622, 755221, 75192, '<td valign="top">I used to love playing this! The shot itself is a bit flat and the colours could have done with a boost - i.e. saturation. I think a macro of maybe one of the cars with the people in, with maybe the board in the background might have been better.</td>', 'I used to love playing this! The shot itself is a bit flat and the colours could have done with a boost - i.e. saturation. I think a macro of maybe one of the cars with the people in, with maybe the board in the background might have been better.', '2009-01-13 18:52:29.000000', NULL, 1),
(5189623, 755226, 76598, '<td valign="top">I like the shadows from the figures.  I think a single figure would have conveyed lonliness in someway, but this seems only to convey cold.  The lens flare is really distracting.</td>', 'I like the shadows from the figures.  I think a single figure would have conveyed lonliness in someway, but this seems only to convey cold.  The lens flare is really distracting.', '2009-01-13 18:52:50.000000', NULL, 1),
