(5189648, 754817, 15204, '<td valign="top">I like the wide angle perspective and how he balances with the tree so well.  Beautiful colors with the blue and the green.  Very nicely done. 7 from me.</td>', 'I like the wide angle perspective and how he balances with the tree so well.  Beautiful colors with the blue and the green.  Very nicely done. 7 from me.', '2009-01-13 19:16:00.000000', NULL, 1),
(5189650, 754235, 15204, '<td valign="top">This one reminds me of a painting more than a photograph (which I like about it).  6 from me.</td>', 'This one reminds me of a painting more than a photograph (which I like about it).  6 from me.', '2009-01-13 19:18:02.000000', NULL, 1),
(5189654, 754941, 15204, '<td valign="top">If it was possible, I think this would be great from a lower camera position so that the silohuette was above the horizon.  Everything else about the image is stunning.</td>', 'If it was possible, I think this would be great from a lower camera position so that the silohuette was above the horizon.  Everything else about the image is stunning.', '2009-01-13 19:21:29.000000', NULL, 1),
