(5190239, 755274, 96574, '<td valign="top">very interesting place for a cow</td>', 'very interesting place for a cow', '2009-01-14 05:12:33.000000', NULL, 1),
(5190348, 755072, 65234, '<td valign="top">Very interesting image.  The hooded figure is relatively genderless and featureless, which leaves everything open to the imagination.  I just have to wonder what''s being contemplated.  Could be a lost love or a hopeless life or thinking through a problem or just trying to remember what to get at the store.  Love the composition and the darkness of the bridge, its reflection, and our subject.  The timeless tones.  And the brooding sky and the interesting architecture if I let my eyes wander around.  Great image.</td>', 'Very interesting image.  The hooded figure is relatively genderless and featureless, which leaves everything open to the imagination.  I just have to wonder what''s being contemplated.  Could be a lost love or a hopeless life or thinking through a problem or just trying to remember what to get at the store.  Love the composition and the darkness of the bridge, its reflection, and our subject.  The timeless tones.  And the brooding sky and the interesting architecture if I let my eyes wander around.  Great image.', '2009-01-14 07:16:47.000000', NULL, 1),
(5190349, 754969, 65234, '<td valign="top">What an adorable little creature!!  He looks like he''s floating above the sand.  Nice to have a bit of something on the left there to lend a little perspective, too.  And I love the title :-)</td>', 'What an adorable little creature!!  He looks like he''s floating above the sand.  Nice to have a bit of something on the left there to lend a little perspective, too.  And I love the title :-)', '2009-01-14 07:16:52.000000', NULL, 1),
(5190350, 755222, 65234, '<td valign="top">Very, very sweet story well captured here :-)</td>', 'Very, very sweet story well captured here :-)', '2009-01-14 07:17:17.000000', NULL, 1),
(5190351, 754871, 65234, '<td valign="top">Stunner of a wildlife shot!  Phenomenal detail to see those snowflakes on the bear''s fur.  I''d like to see this lightened and sharpened just a tad more to really bring out the expression on the bear''s face but it''s a terrific capture.</td>', 'Stunner of a wildlife shot!  Phenomenal detail to see those snowflakes on the bear''s fur.  I''d like to see this lightened and sharpened just a tad more to really bring out the expression on the bear''s face but it''s a terrific capture.', '2009-01-14 07:17:20.000000', NULL, 1),
(5190352, 755190, 65234, '<td valign="top">Gorgeous portrait.  I have one of these guys hanging out in my neighborhood; he''s fascinating to watch.</td>', 'Gorgeous portrait.  I have one of these guys hanging out in my neighborhood; he''s fascinating to watch.', '2009-01-14 07:17:27.000000', NULL, 1),
(5190353, 754866, 65234, '<td valign="top">Wow!!!  Unusual and wonderfully active pose and terrific detail on the face.</td>', 'Wow!!!  Unusual and wonderfully active pose and terrific detail on the face.', '2009-01-14 07:17:32.000000', NULL, 1),
(5190354, 755031, 65234, '<td valign="top">Beautifully done; just the right amount of light outlining them.</td>', 'Beautifully done; just the right amount of light outlining them.', '2009-01-14 07:17:37.000000', NULL, 1),
(5190355, 754741, 65234, '<td valign="top">Love this portrait!!  Wonderful light and expression and that ear on the pillow is a great touch.</td>', 'Love this portrait!!  Wonderful light and expression and that ear on the pillow is a great touch.', '2009-01-14 07:17:50.000000', NULL, 1),
(5190356, 755370, 65234, '<td valign="top">Rather an astounding capture!  I don''t want to be on the receiving end of that bite =:-O</td>', 'Rather an astounding capture!  I don''t want to be on the receiving end of that bite =:-O', '2009-01-14 07:18:01.000000', NULL, 1),
