INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5190362, 754570, 65234, '<td valign="top">That is one heck of a macro!!  Astounding detail.  That foot coming round to hug the blade of grass is rather creepy!</td>', 'That is one heck of a macro!!  Astounding detail.  That foot coming round to hug the blade of grass is rather creepy!', '2009-01-14 07:19:22.000000', NULL, 1),
(5190363, 755158, 65234, '<td valign="top">This is beautifully soft; I really like the DOF and processing.</td>', 'This is beautifully soft; I really like the DOF and processing.', '2009-01-14 07:19:26.000000', NULL, 1),
(5190364, 755066, 65234, '<td valign="top">LOL!  Great title and intriguing image.  Almost looks like the fish is in outer space.</td>', 'LOL!  Great title and intriguing image.  Almost looks like the fish is in outer space.', '2009-01-14 07:19:37.000000', NULL, 1),
(5190365, 754772, 65234, '<td valign="top">Sweet portrait; those eyes just grab my attention and I want to do something to make her smile (looks like a her to my imagination).</td>', 'Sweet portrait; those eyes just grab my attention and I want to do something to make her smile (looks like a her to my imagination).', '2009-01-14 07:19:44.000000', NULL, 1),
(5190366, 754005, 65234, '<td valign="top">Looks like he finally scaled the pinnacle on the mountain ;-)  Not the usual background for a bug shot; I like it!</td>', 'Looks like he finally scaled the pinnacle on the mountain ;-)  Not the usual background for a bug shot; I like it!', '2009-01-14 07:19:51.000000', NULL, 1),
(5190367, 753768, 65234, '<td valign="top">Nice shot; just want a bit of the catchlight in the eye brought out to really bring him to life.</td>', 'Nice shot; just want a bit of the catchlight in the eye brought out to really bring him to life.', '2009-01-14 07:20:44.000000', NULL, 1),
(5190368, 755404, 65234, '<td valign="top">Very cool bug!  Love seeing half of him as a shadow.</td>', 'Very cool bug!  Love seeing half of him as a shadow.', '2009-01-14 07:20:56.000000', NULL, 1),
(5190369, 755029, 65234, '<td valign="top">Works well as a macro with interesting shapes and textures; DOF is spot on IMO.</td>', 'Works well as a macro with interesting shapes and textures; DOF is spot on IMO.', '2009-01-14 07:21:53.000000', NULL, 1),
(5190370, 755352, 65234, '<td valign="top">Looking beatifically happy :-)</td>', 'Looking beatifically happy :-)', '2009-01-14 07:21:59.000000', NULL, 1),
(5190371, 755386, 65234, '<td valign="top">Cooperative little model!  I like your DOF and the simplicity of the shot.</td>', 'Cooperative little model!  I like your DOF and the simplicity of the shot.', '2009-01-14 07:22:03.000000', NULL, 1),
(5190372, 755139, 65234, '<td valign="top">Gotta'' love sheep :-)  The curly hairdo is wonderful!</td>', 'Gotta'' love sheep :-)  The curly hairdo is wonderful!', '2009-01-14 07:22:08.000000', NULL, 1),
(5190373, 755171, 65234, '<td valign="top">OMG, that''s so cute!!  Great perspective and despite his almost worried expression I bet he was having a blast :-)</td>', 'OMG, that''s so cute!!  Great perspective and despite his almost worried expression I bet he was having a blast :-)', '2009-01-14 07:22:16.000000', NULL, 1),
(5190374, 755051, 65234, '<td valign="top">Love the softness of this and the harsh reality implied by the ear tags and what look to be tear stains.</td>', 'Love the softness of this and the harsh reality implied by the ear tags and what look to be tear stains.', '2009-01-14 07:22:22.000000', NULL, 1),
(5190376, 755251, 65234, '<td valign="top">Intriguing cactus.  Looks ancient.</td>', 'Intriguing cactus.  Looks ancient.', '2009-01-14 07:23:26.000000', NULL, 1),
(5190377, 755340, 65234, '<td valign="top">Nice colors and composition.  The string of "beads" (beans of some kind?) look cheerfully busy, like kids just getting out of school and bouncing out the door, pushing and shoving and giggling.</td>', 'Nice colors and composition.  The string of "beads" (beans of some kind?) look cheerfully busy, like kids just getting out of school and bouncing out the door, pushing and shoving and giggling.', '2009-01-14 07:23:40.000000', NULL, 1),
(5190378, 753595, 65234, '<td valign="top">They sort of look like angel wings.  Very delicate and ethereal.</td>', 'They sort of look like angel wings.  Very delicate and ethereal.', '2009-01-14 07:23:44.000000', NULL, 1),
(5190379, 754058, 65234, '<td valign="top">Looks almost bashful.  Very interesting light.</td>', 'Looks almost bashful.  Very interesting light.', '2009-01-14 07:23:48.000000', NULL, 1),
(5190380, 755364, 65234, '<td valign="top">Oh, they''re cute!  They look like they''re whispering little-girl secrets, which means a gigglefest should be breaking out soon ;-)</td>', 'Oh, they''re cute!  They look like they''re whispering little-girl secrets, which means a gigglefest should be breaking out soon ;-)', '2009-01-14 07:25:10.000000', NULL, 1),
(5190381, 754478, 65234, '<td valign="top">Beautiful feather detail!  Looks like a Little Blue Heron; very pretty bird.  And quite intent on his meal.</td>', 'Beautiful feather detail!  Looks like a Little Blue Heron; very pretty bird.  And quite intent on his meal.', '2009-01-14 07:26:27.000000', NULL, 1),
(5190383, 755165, 65234, '<td valign="top">Amazingly close view of an ant.</td>', 'Amazingly close view of an ant.', '2009-01-14 07:26:58.000000', NULL, 1),
(5190384, 755126, 65234, '<td valign="top">Love his imperious expression.</td>', 'Love his imperious expression.', '2009-01-14 07:27:07.000000', NULL, 1),
(5190385, 754778, 65234, '<td valign="top">Nicely in-your-face, which describes so many cats'' personalities ;-)  The eyes look a little cartoonish ... I think it''s the perfectly identical round catchlights on the pitch black pupils.  I think I expect to see little bits of light reflected off other areas in the pupil to make them look less flat.  But they do have a lot of impact.</td>', 'Nicely in-your-face, which describes so many cats'' personalities ;-)  The eyes look a little cartoonish ... I think it''s the perfectly identical round catchlights on the pitch black pupils.  I think I expect to see little bits of light reflected off other areas in the pupil to make them look less flat.  But they do have a lot of impact.', '2009-01-14 07:27:19.000000', NULL, 1),
(5190386, 754853, 65234, '<td valign="top">Fun image with all the reflections of real and not-so-real people interspersed.</td>', 'Fun image with all the reflections of real and not-so-real people interspersed.', '2009-01-14 07:27:21.000000', NULL, 1),
(5190387, 755259, 65234, '<td valign="top">Serious title but the elephant towel doesn''t look the part ;-)  Although it is darned cute; I need to invest in something like that when I have grandkids!  Nice, even lighting and I love her little ringlets and innocent expression.</td>', 'Serious title but the elephant towel doesn''t look the part ;-)  Although it is darned cute; I need to invest in something like that when I have grandkids!  Nice, even lighting and I love her little ringlets and innocent expression.', '2009-01-14 07:27:31.000000', NULL, 1),
(5190388, 755185, 65234, '<td valign="top">Sweet moment to capture.  Don''t know if you''re a fan of this sort of processing but a duplicate layer blurred and blended in multiply mode lends a marvelous dreaminess which I think really suits this kind of image.  Might be fun to try.</td>', 'Sweet moment to capture.  Don''t know if you''re a fan of this sort of processing but a duplicate layer blurred and blended in multiply mode lends a marvelous dreaminess which I think really suits this kind of image.  Might be fun to try.', '2009-01-14 07:27:41.000000', NULL, 1),
(5190414, 754292, 93160, '<td valign="top">Very nice lighting, great facial expression.</td>', 'Very nice lighting, great facial expression.', '2009-01-14 08:14:50.000000', NULL, 1),
(5190418, 755356, 79955, '<td valign="top">color tones not really my taste , still nice shot, excellent detail, lovely pose, 8</td>', 'color tones not really my taste , still nice shot, excellent detail, lovely pose, 8', '2009-01-14 08:19:07.000000', NULL, 1),
(5190818, 754934, 73235, '<td valign="top">good action capture. the slight motion blur does help with seeing the action.</td>', 'good action capture. the slight motion blur does help with seeing the action.', '2009-01-14 11:49:17.000000', NULL, 1),
(5190821, 754479, 73235, '<td valign="top">I wish I could see a little more of the surrounding. the bokeh in the background helps focuing on your subject.</td>', 'I wish I could see a little more of the surrounding. the bokeh in the background helps focuing on your subject.', '2009-01-14 11:50:43.000000', NULL, 1),
