(5190850, 754941, 73235, '<td valign="top">Couldn''t you have told your model to straighten out his/her arms with the horizon ? (LOL) great warm tones and good timing of your trigger-finger :)</td>', 'Couldn''t you have told your model to straighten out his/her arms with the horizon ? (LOL) great warm tones and good timing of your trigger-finger :)', '2009-01-14 12:00:04.000000', NULL, 1),
