INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5192777, 755342, 83313, '<td valign="top">Your filesize is very small at 53k. Much of that is accounted for by a dark background that compressed very well, however, you may have been able to squeeze a little more detail and clarity from this by using less compression. you had another 147k to use.<br/> <br/>This is pretty simple and straight forward, but the lighting and colors are good.</td>', 'Your filesize is very small at 53k. Much of that is accounted for by a dark background that compressed very well, however, you may have been able to squeeze a little more detail and clarity from this by using less compression. you had another 147k to use. This is pretty simple and straight forward, but the lighting and colors are good.', '2009-01-15 13:03:13.000000', NULL, 1),
(5192779, 754701, 73235, '<td valign="top">successfully framed and well toned</td>', 'successfully framed and well toned', '2009-01-15 13:05:06.000000', NULL, 1),
(5192781, 754051, 73235, '<td valign="top">great detail in the fur,</td>', 'great detail in the fur,', '2009-01-15 13:05:47.000000', NULL, 1),
(5192782, 754483, 83313, '<td valign="top">A pretty good capture bumped up a couple of notches by an exceptional scene. Might fit into the "business person" challenge as well.</td>', 'A pretty good capture bumped up a couple of notches by an exceptional scene. Might fit into the "business person" challenge as well.', '2009-01-15 13:05:57.000000', NULL, 1),
(5192784, 754903, 73235, '<td valign="top">imaginative interpretation of the challenge.</td>', 'imaginative interpretation of the challenge.', '2009-01-15 13:06:28.000000', NULL, 1),
(5192786, 755259, 83313, '<td valign="top">Very cute. Love the elephant bathrobe.</td>', 'Very cute. Love the elephant bathrobe.', '2009-01-15 13:07:25.000000', NULL, 1),
(5192791, 754701, 83313, '<td valign="top">Great candid. The dark areas in the corner suggest to me that you may have been peeking out from somwhere.</td>', 'Great candid. The dark areas in the corner suggest to me that you may have been peeking out from somwhere.', '2009-01-15 13:09:09.000000', NULL, 1),
(5192795, 755372, 83313, '<td valign="top">A little bit of blur on the faces, but this is a real life, active scene. Marginally a snapshot, but this is as good as snapshots get. Looks like they are having loads of fun.</td>', 'A little bit of blur on the faces, but this is a real life, active scene. Marginally a snapshot, but this is as good as snapshots get. Looks like they are having loads of fun.', '2009-01-15 13:11:30.000000', NULL, 1),
(5192797, 753915, 83313, '<td valign="top">As long as he doesn''t try to sell me any insurance, I like him.</td>', 'As long as he doesn''t try to sell me any insurance, I like him.', '2009-01-15 13:12:31.000000', NULL, 1),
(5192802, 755333, 83313, '<td valign="top">Now that''s cool. How did you get something underwater to photograph so clearly?</td>', 'Now that''s cool. How did you get something underwater to photograph so clearly?', '2009-01-15 13:13:48.000000', NULL, 1),
(5192824, 755129, 83313, '<td valign="top">I suggest to the court that this snowball was not acting it''s own. There was a greater conspiracy going on here and a mystery snowball thrower that has not yet been identified. But don''t worry, we''ve got "CSI: Duluth" on the case.</td>', 'I suggest to the court that this snowball was not acting it''s own. There was a greater conspiracy going on here and a mystery snowball thrower that has not yet been identified. But don''t worry, we''ve got "CSI: Duluth" on the case.', '2009-01-15 13:19:34.000000', NULL, 1),
(5192835, 753988, 83313, '<td valign="top">Colors seem washed out or artificial somehow (From flash perhaps?). I think there is also a lot of JPEG compression robbing detail. I can especially see some artifacting around her mouth and nose. Your 67k file size indicates you could have used much less compression and gotten much more detail into this. Always save your file as large as possible within challenge limits. (200k for this one.)</td>', 'Colors seem washed out or artificial somehow (From flash perhaps?). I think there is also a lot of JPEG compression robbing detail. I can especially see some artifacting around her mouth and nose. Your 67k file size indicates you could have used much less compression and gotten much more detail into this. Always save your file as large as possible within challenge limits. (200k for this one.)', '2009-01-15 13:23:46.000000', NULL, 1),
(5192850, 755016, 83313, '<td valign="top">Some good potential, but this comes off as a bit dull and soft. I copied it into my image editor out of curiosity, and some quick adjustments of levels, curves, saturation, clarify and sharpening really made it pop a lot more.</td>', 'Some good potential, but this comes off as a bit dull and soft. I copied it into my image editor out of curiosity, and some quick adjustments of levels, curves, saturation, clarify and sharpening really made it pop a lot more.', '2009-01-15 13:31:14.000000', NULL, 1),
(5192876, 755345, 83313, '<td valign="top">I''m going to to guess it stands for the "Secret International League Headquarters Of Ultimate Espionage Trained Travellers (Europe)"<br/> <br/>I hope you appreciate the work that went into that comment. It took me 10 minutes to come up with the acronym.</td>', 'I''m going to to guess it stands for the "Secret International League Headquarters Of Ultimate Espionage Trained Travellers (Europe)" I hope you appreciate the work that went into that comment. It took me 10 minutes to come up with the acronym.', '2009-01-15 13:41:50.000000', NULL, 1),
(5192877, 754631, 83313, '<td valign="top">Just a great portrait of this kid.</td>', 'Just a great portrait of this kid.', '2009-01-15 13:42:26.000000', NULL, 1),
(5192936, 755333, 16046, '<td valign="top">Awesome image, well lit, congrats in advance</td>', 'Awesome image, well lit, congrats in advance', '2009-01-15 14:10:39.000000', NULL, 1),
(5192941, 754283, 16046, '<td valign="top">Awesome color, well done</td>', 'Awesome color, well done', '2009-01-15 14:13:45.000000', NULL, 1),
(5192945, 754650, 98141, '<td valign="top">To me, this feels like a picture of ghosts. It has the essence of something alive, yet the colors and lighting don''t feel vibrant, they feel like they''re from the past. I like this a lot.</td>', 'To me, this feels like a picture of ghosts. It has the essence of something alive, yet the colors and lighting don''t feel vibrant, they feel like they''re from the past. I like this a lot.', '2009-01-15 14:15:34.000000', NULL, 1),
(5192946, 755298, 16046, '<td valign="top">Wonderful capture, well done</td>', 'Wonderful capture, well done', '2009-01-15 14:16:00.000000', NULL, 1),
(5192947, 755215, 98141, '<td valign="top">It is definitely alive! The lighting feels very harsh to me though. But, frogs have been doing well recently.</td>', 'It is definitely alive! The lighting feels very harsh to me though. But, frogs have been doing well recently.', '2009-01-15 14:16:06.000000', NULL, 1),
(5192950, 755067, 98141, '<td valign="top">Beautiful, soft, great contrast and lighting. I love this.</td>', 'Beautiful, soft, great contrast and lighting. I love this.', '2009-01-15 14:16:26.000000', NULL, 1),
(5192951, 755299, 16046, '<td valign="top">Love those IKEA vases, nice</td>', 'Love those IKEA vases, nice', '2009-01-15 14:16:45.000000', NULL, 1),
(5192958, 754941, 16046, '<td valign="top">Terrific image, well executed</td>', 'Terrific image, well executed', '2009-01-15 14:18:14.000000', NULL, 1),
(5192960, 754868, 98141, '<td valign="top">An interesting portrait for a "life" challenge, though it definitely qualifies it is different from the entries I expected to see, and that''s good. I think a different angle might add more visual interest to this, perhaps a more extreme high angle?</td>', 'An interesting portrait for a "life" challenge, though it definitely qualifies it is different from the entries I expected to see, and that''s good. I think a different angle might add more visual interest to this, perhaps a more extreme high angle?', '2009-01-15 14:18:27.000000', NULL, 1),
(5192963, 755401, 98141, '<td valign="top">I love that we can see the roots from the bulb. I don''t care much for the background, it feels too dramatic for me when combined with the low angle and the lighting.</td>', 'I love that we can see the roots from the bulb. I don''t care much for the background, it feels too dramatic for me when combined with the low angle and the lighting.', '2009-01-15 14:20:23.000000', NULL, 1),
(5192965, 754058, 16046, '<td valign="top">Interesting lighting, well done</td>', 'Interesting lighting, well done', '2009-01-15 14:20:45.000000', NULL, 1),
(5192971, 754565, 98141, '<td valign="top">I wish this were a bit sharper, I liek the idea of it. I think a lower angle that included less of the dark rocks would let the silhouettes of the birds stand out more against a bright background.</td>', 'I wish this were a bit sharper, I liek the idea of it. I think a lower angle that included less of the dark rocks would let the silhouettes of the birds stand out more against a bright background.', '2009-01-15 14:23:38.000000', NULL, 1),
(5192972, 754433, 16046, '<td valign="top">Super macro, great detail with awesome lighting</td>', 'Super macro, great detail with awesome lighting', '2009-01-15 14:24:27.000000', NULL, 1),
(5192976, 755251, 98141, '<td valign="top">Excellent contrast, excellent lighting! One of my favs so far.</td>', 'Excellent contrast, excellent lighting! One of my favs so far.', '2009-01-15 14:25:52.000000', NULL, 1),
(5192978, 754479, 98141, '<td valign="top">This is a cool subject, but I feel like something is missing. Perhaps centering it differently or sharpening it up a bit. Nice DOF.</td>', 'This is a cool subject, but I feel like something is missing. Perhaps centering it differently or sharpening it up a bit. Nice DOF.', '2009-01-15 14:26:30.000000', NULL, 1),
(5192982, 755362, 98141, '<td valign="top">To me, not sharp enough and it falls a little flat.</td>', 'To me, not sharp enough and it falls a little flat.', '2009-01-15 14:28:32.000000', NULL, 1),
(5193014, 755299, 98141, '<td valign="top">Great lighting, simple subject, nice colors. I think this will do well.</td>', 'Great lighting, simple subject, nice colors. I think this will do well.', '2009-01-15 14:57:30.000000', NULL, 1),
(5193019, 755209, 47470, '<td valign="top">The title made me laugh : )</td>', 'The title made me laugh : )', '2009-01-15 15:04:12.000000', NULL, 1),
(5193020, 754565, 47470, '<td valign="top">This doesn''t seem very sharp.</td>', 'This doesn''t seem very sharp.', '2009-01-15 15:05:16.000000', NULL, 1),
(5193021, 755361, 47470, '<td valign="top">Nice focus on the eyes, but the crop is a bit too tight for me.</td>', 'Nice focus on the eyes, but the crop is a bit too tight for me.', '2009-01-15 15:06:02.000000', NULL, 1),
(5193023, 755361, 38162, '<td valign="top">title hurts this one - "through new eyes" would suffice - let the pic speak</td>', 'title hurts this one - "through new eyes" would suffice - let the pic speak', '2009-01-15 15:06:32.000000', NULL, 1),
(5193024, 754543, 47470, '<td valign="top">There''s a bit of motion blur, but nice framing.</td>', 'There''s a bit of motion blur, but nice framing.', '2009-01-15 15:07:09.000000', NULL, 1),
(5193025, 754522, 38162, '<td valign="top">border hurts this</td>', 'border hurts this', '2009-01-15 15:07:37.000000', NULL, 1),
(5193027, 755285, 47470, '<td valign="top">Cute lolcat!  Nice capture.</td>', 'Cute lolcat!  Nice capture.', '2009-01-15 15:07:47.000000', NULL, 1),
(5193033, 754483, 98141, '<td valign="top">EW! Nice DOF, great colors, great capture!</td>', 'EW! Nice DOF, great colors, great capture!', '2009-01-15 15:10:58.000000', NULL, 1),
(5193035, 754759, 47470, '<td valign="top">Nice use of the leading line.  I might have fixed the tilt of the column on the left side.<br/> <br/>I don''t really like that the inside of this mall looks like the inside of a church (but that really doesn''t have much to do with you unless you were the architect!).</td>', 'Nice use of the leading line.  I might have fixed the tilt of the column on the left side. I don''t really like that the inside of this mall looks like the inside of a church (but that really doesn''t have much to do with you unless you were the architect!).', '2009-01-15 15:11:03.000000', NULL, 1),
(5193036, 755221, 98141, '<td valign="top">A little dark and the contrast could be upped a smidge. I like the unique take on the challenge though, so bonus point for that.</td>', 'A little dark and the contrast could be upped a smidge. I like the unique take on the challenge though, so bonus point for that.', '2009-01-15 15:11:39.000000', NULL, 1),
(5193038, 754570, 98141, '<td valign="top">Whoa, this is really cool! I love all the textures, in the eyes, on the legs, the hairs. This is a truly amazing macro shot.</td>', 'Whoa, this is really cool! I love all the textures, in the eyes, on the legs, the hairs. This is a truly amazing macro shot.', '2009-01-15 15:12:26.000000', NULL, 1),
(5193043, 755242, 98141, '<td valign="top">I wish that the eyes were sharper, the soft focus works well everywhere else but I wish the eyes popped a little more. Beautiful baby :)</td>', 'I wish that the eyes were sharper, the soft focus works well everywhere else but I wish the eyes popped a little more. Beautiful baby :)', '2009-01-15 15:13:45.000000', NULL, 1),
(5193048, 754789, 98141, '<td valign="top">Great lines, nice colors, this pops nicely. I''d prefer for the white bit to be a little more off-center, since that''s where my eye wants to focus.</td>', 'Great lines, nice colors, this pops nicely. I''d prefer for the white bit to be a little more off-center, since that''s where my eye wants to focus.', '2009-01-15 15:17:28.000000', NULL, 1),
(5193049, 755288, 98141, '<td valign="top">While I like this take on the challenge, I feel that the subject would be more visually engaging were it not right in the center of the pic. Perhaps some more negative space to make the subject appear more "lonely?"</td>', 'While I like this take on the challenge, I feel that the subject would be more visually engaging were it not right in the center of the pic. Perhaps some more negative space to make the subject appear more "lonely?"', '2009-01-15 15:18:32.000000', NULL, 1),
(5193050, 755286, 98141, '<td valign="top">Fantastic bokeh! I love this although I am tired of looking out my window and seeing similar subjects for the past couple of months ;)</td>', 'Fantastic bokeh! I love this although I am tired of looking out my window and seeing similar subjects for the past couple of months ;)', '2009-01-15 15:19:06.000000', NULL, 1),
(5193053, 754275, 98141, '<td valign="top">I love the way the blue pops, I love the lines in this and I love the motion in the wheel but maintaining the clarity of the eye. Well done, would like to read your capture/editing steps :)</td>', 'I love the way the blue pops, I love the lines in this and I love the motion in the wheel but maintaining the clarity of the eye. Well done, would like to read your capture/editing steps :)', '2009-01-15 15:20:20.000000', NULL, 1),
(5193055, 754308, 98141, '<td valign="top">Awwwww! So cute! Great capture, but it looks warm and sunny where you are, mind if I join you? :D Great capture of the soft texture of the fur, nice DOF as well.</td>', 'Awwwww! So cute! Great capture, but it looks warm and sunny where you are, mind if I join you? :D Great capture of the soft texture of the fur, nice DOF as well.', '2009-01-15 15:21:20.000000', NULL, 1),
(5193060, 754283, 98141, '<td valign="top">I love the subject but the lighting falls very flat and feels unnatural to me. I also find the blank space in the upper right corner distracting.</td>', 'I love the subject but the lighting falls very flat and feels unnatural to me. I also find the blank space in the upper right corner distracting.', '2009-01-15 15:23:16.000000', NULL, 1),
(5193061, 755285, 98141, '<td valign="top">HAhahahaha! I know there''s a lot of cat-haters here (for reasons I still haven''t discovered), but I think this is hilarious and also a well-executed shot. Good job.</td>', 'HAhahahaha! I know there''s a lot of cat-haters here (for reasons I still haven''t discovered), but I think this is hilarious and also a well-executed shot. Good job.', '2009-01-15 15:24:01.000000', NULL, 1),
(5193062, 754771, 98141, '<td valign="top">Love the use of open space here, love their expressions. Great colors, too. Wonderful shot.</td>', 'Love the use of open space here, love their expressions. Great colors, too. Wonderful shot.', '2009-01-15 15:24:26.000000', NULL, 1),
(5193063, 754284, 98141, '<td valign="top">Beautiful and vibrant! Great subject, nice composition and I enjoy this one a lot.</td>', 'Beautiful and vibrant! Great subject, nice composition and I enjoy this one a lot.', '2009-01-15 15:24:49.000000', NULL, 1),
(5193064, 755226, 38162, '<td valign="top">title really hurts this one. nice capture.</td>', 'title really hurts this one. nice capture.', '2009-01-15 15:24:54.000000', NULL, 1),
(5193066, 755349, 38162, '<td valign="top">wow - this title really hurts this - pic says 1000 words and all that.  composition is great but oversat doesnt make it work.</td>', 'wow - this title really hurts this - pic says 1000 words and all that.  composition is great but oversat doesnt make it work.', '2009-01-15 15:28:01.000000', NULL, 1),
(5193070, 754292, 38162, '<td valign="top">rule of thirds for crop would really make this terrific - her left eye is too centered.  great lighting and super capture.</td>', 'rule of thirds for crop would really make this terrific - her left eye is too centered.  great lighting and super capture.', '2009-01-15 15:30:41.000000', NULL, 1),
(5193073, 755185, 47470, '<td valign="top">Nice sharpness on the horses.  Too bad the mother''s tail is covering the baby''s face.  I wonder what this would look like with the background darkened or with a vignette.</td>', 'Nice sharpness on the horses.  Too bad the mother''s tail is covering the baby''s face.  I wonder what this would look like with the background darkened or with a vignette.', '2009-01-15 15:31:10.000000', NULL, 1),
(5193076, 755250, 38162, '<td valign="top">terrific capture here - would like blacks to pop more.</td>', 'terrific capture here - would like blacks to pop more.', '2009-01-15 15:33:25.000000', NULL, 1),
(5193077, 755190, 38162, '<td valign="top">dont like the crop - a rule of thirds crop to put the eye off center would really help this one.  sharp and great tonality.</td>', 'dont like the crop - a rule of thirds crop to put the eye off center would really help this one.  sharp and great tonality.', '2009-01-15 15:34:25.000000', NULL, 1),
(5193086, 755138, 38162, '<td valign="top">a square crop would really make this one.  great capture.</td>', 'a square crop would really make this one.  great capture.', '2009-01-15 15:37:19.000000', NULL, 1),
(5193090, 755403, 47470, '<td valign="top">I like the use of the tilt, but I think it''s a little dark.</td>', 'I like the use of the tilt, but I think it''s a little dark.', '2009-01-15 15:38:53.000000', NULL, 1),
(5193094, 755177, 47470, '<td valign="top">I think I would have cropped the white sky off the top to make sure the eye stays with the man.</td>', 'I think I would have cropped the white sky off the top to make sure the eye stays with the man.', '2009-01-15 15:41:26.000000', NULL, 1),
(5193095, 754701, 38162, '<td valign="top">square crop would have really made this one - he is too centered.  great mood.  super tonality.</td>', 'square crop would have really made this one - he is too centered.  great mood.  super tonality.', '2009-01-15 15:42:15.000000', NULL, 1),
(5193097, 754771, 47470, '<td valign="top">I''m not sure I like all the space.  The kids are happy and having fun, but the extra space seems to imply that their happiness is small and maybe even trivial.  I''d like to think that happiness is pretty important in life.  Dunno.  Just my interpretation of the shot.</td>', 'I''m not sure I like all the space.  The kids are happy and having fun, but the extra space seems to imply that their happiness is small and maybe even trivial.  I''d like to think that happiness is pretty important in life.  Dunno.  Just my interpretation of the shot.', '2009-01-15 15:44:43.000000', NULL, 1),
(5193104, 754687, 47470, '<td valign="top">Hmm, the darker side of life.  Not too many of these entered.<br/> <br/>I like the lighting and the detail in his skin/beard.  I might have traded some of the negative space above his head for a bit more of his shoulder/body, but it''s nice overall.  I even kinda like the spacing in the title, even though that usually bugs me : )</td>', 'Hmm, the darker side of life.  Not too many of these entered. I like the lighting and the detail in his skin/beard.  I might have traded some of the negative space above his head for a bit more of his shoulder/body, but it''s nice overall.  I even kinda like the spacing in the title, even though that usually bugs me : )', '2009-01-15 15:48:11.000000', NULL, 1),
(5193106, 753822, 47470, '<td valign="top">I think it might look better if there was a hair light/some kind of back lighting so she didn''t blend in with the background.</td>', 'I think it might look better if there was a hair light/some kind of back lighting so she didn''t blend in with the background.', '2009-01-15 15:49:21.000000', NULL, 1),
(5193107, 754147, 47470, '<td valign="top">Interesting shot.  I wish I could see their whole faces though.  A little bit of sharpening would really make this pop too.</td>', 'Interesting shot.  I wish I could see their whole faces though.  A little bit of sharpening would really make this pop too.', '2009-01-15 15:50:26.000000', NULL, 1),
(5193111, 754902, 47470, '<td valign="top">The lighting is very pretty, but the unusual makeup might have seemed more natural within the shot if she were wearing a simpler shirt.  Nice vignetting.</td>', 'The lighting is very pretty, but the unusual makeup might have seemed more natural within the shot if she were wearing a simpler shirt.  Nice vignetting.', '2009-01-15 15:55:27.000000', NULL, 1),
(5193121, 754843, 47470, '<td valign="top">I like the colorfulness, but I wish it were a little sharper.</td>', 'I like the colorfulness, but I wish it were a little sharper.', '2009-01-15 16:08:04.000000', NULL, 1),
(5193122, 755052, 47470, '<td valign="top">I wish the larger drop had been the one in focus.</td>', 'I wish the larger drop had been the one in focus.', '2009-01-15 16:09:28.000000', NULL, 1),
(5193123, 754235, 47470, '<td valign="top">This would look nicer with some added sharpness and contrast.</td>', 'This would look nicer with some added sharpness and contrast.', '2009-01-15 16:10:45.000000', NULL, 1),
(5193125, 755066, 47470, '<td valign="top">Very interesting composition.  I like the centered-ness.  Nice detail and color too!</td>', 'Very interesting composition.  I like the centered-ness.  Nice detail and color too!', '2009-01-15 16:11:05.000000', NULL, 1),
(5193144, 755340, 75192, '<td valign="top">I like the textures in this one. The green hue of the peas(?) is especially appealing. The glass of the window makes an excellent backdrop. I don''t really like the reflection bouncing off the blue vase though.... I think a vase which didn''t reflect would have been better and might have added a good rough texture to balance out the picture.</td>', 'I like the textures in this one. The green hue of the peas(?) is especially appealing. The glass of the window makes an excellent backdrop. I don''t really like the reflection bouncing off the blue vase though.... I think a vase which didn''t reflect would have been better and might have added a good rough texture to balance out the picture.', '2009-01-15 16:24:08.000000', NULL, 1),
(5193151, 755356, 84779, '<td valign="top">awww my dog looks just like that when his hair is cut</td>', 'awww my dog looks just like that when his hair is cut', '2009-01-15 16:34:11.000000', NULL, 1),
