(5195425, 753941, 73235, '<td valign="top">did you ask her to hold her position for you to make this shot?</td>', 'did you ask her to hold her position for you to make this shot?', '2009-01-16 12:12:45.000000', NULL, 1),
(5195435, 754360, 73235, '<td valign="top">this must be a very tight crop with the noise as visible as it is in the sky and snow. the crop also makes the pic to be very soft.</td>', 'this must be a very tight crop with the noise as visible as it is in the sky and snow. the crop also makes the pic to be very soft.', '2009-01-16 12:13:56.000000', NULL, 1),
(5195443, 754969, 39880, '<td valign="top">This is a nice minimalist shot.  Nice DOF, and composition.  Well done.</td>', 'This is a nice minimalist shot.  Nice DOF, and composition.  Well done.', '2009-01-16 12:15:30.000000', NULL, 1),
(5195450, 755386, 39880, '<td valign="top">Great detail.  I like the reflection.</td>', 'Great detail.  I like the reflection.', '2009-01-16 12:16:12.000000', NULL, 1),
(5195452, 755340, 73235, '<td valign="top">very good composition and DOF. the big blue pot is pulling me right into the picture. then the lines of the strings capture me to explore each of these beads. the background almost featureless helps me staying focused on the beads. Guess you got it by now that I like your shot, right?</td>', 'very good composition and DOF. the big blue pot is pulling me right into the picture. then the lines of the strings capture me to explore each of these beads. the background almost featureless helps me staying focused on the beads. Guess you got it by now that I like your shot, right?', '2009-01-16 12:16:27.000000', NULL, 1),
(5195456, 753773, 39880, '<td valign="top">I like the bokeh.  It just looks a bit flat.</td>', 'I like the bokeh.  It just looks a bit flat.', '2009-01-16 12:17:27.000000', NULL, 1),
(5195457, 754570, 73235, '<td valign="top">beautiful strong picture with amazing details and sharpness. your focus is spot on.</td>', 'beautiful strong picture with amazing details and sharpness. your focus is spot on.', '2009-01-16 12:17:41.000000', NULL, 1),
(5195458, 755070, 39880, '<td valign="top">This looks a bit distorted.  And really not flattering.</td>', 'This looks a bit distorted.  And really not flattering.', '2009-01-16 12:18:35.000000', NULL, 1),
(5195461, 754949, 73235, '<td valign="top">I like the smooth transition of colors in the sky. I think you oversharpened as there is a very visible halo around the branches and birds, which drastically reduces the quality and becomes even distracting.</td>', 'I like the smooth transition of colors in the sky. I think you oversharpened as there is a very visible halo around the branches and birds, which drastically reduces the quality and becomes even distracting.', '2009-01-16 12:19:26.000000', NULL, 1),
(5195464, 754275, 39880, '<td valign="top">Nice take on the challenge.</td>', 'Nice take on the challenge.', '2009-01-16 12:20:40.000000', NULL, 1),
