(5198429, 755309, 62187, '<td valign="top">Weird, the focus makes me feel like I''m gonna lose my balance...</td>', 'Weird, the focus makes me feel like I''m gonna lose my balance...', '2009-01-17 10:45:41.000000', NULL, 1),
