(5198735, 755129, 62187, '<td valign="top">Excellent focus.</td>', 'Excellent focus.', '2009-01-17 11:23:43.000000', NULL, 1),
(5198739, 753773, 62187, '<td valign="top">I''m not sure what to think. I like it but does it fit the challenge? I don''t know.</td>', 'I''m not sure what to think. I like it but does it fit the challenge? I don''t know.', '2009-01-17 11:24:55.000000', NULL, 1),
(5198747, 754565, 62187, '<td valign="top">The focus on the birds is 3D-ish. The contrast in the background seems kind of faded. I''m wondering why you changed it to black and white - it might have been nice to see in color. ?</td>', 'The focus on the birds is 3D-ish. The contrast in the background seems kind of faded. I''m wondering why you changed it to black and white - it might have been nice to see in color. ?', '2009-01-17 11:27:34.000000', NULL, 1),
(5198752, 754426, 62187, '<td valign="top">A nice composition and contrasting colors.</td>', 'A nice composition and contrasting colors.', '2009-01-17 11:28:31.000000', NULL, 1),
(5198763, 754543, 62187, '<td valign="top">The strong focus point seems to be on the left eye and across the whiskers. I think, for me, the impact might have been stronger if the focus were more on the closer, right eye. Also, while the ''green'' is kinda weak for me, the reds/yellows are very pleasing.</td>', 'The strong focus point seems to be on the left eye and across the whiskers. I think, for me, the impact might have been stronger if the focus were more on the closer, right eye. Also, while the ''green'' is kinda weak for me, the reds/yellows are very pleasing.', '2009-01-17 11:30:43.000000', NULL, 1),
(5198766, 755352, 62187, '<td valign="top">I''m not really into baby photos but your focus is super excellent!</td>', 'I''m not really into baby photos but your focus is super excellent!', '2009-01-17 11:31:16.000000', NULL, 1),
(5198772, 754360, 62187, '<td valign="top">The sky looks a little grainy. Otherwise the photo is pretty cool and kind of has a National Geographic look to it.</td>', 'The sky looks a little grainy. Otherwise the photo is pretty cool and kind of has a National Geographic look to it.', '2009-01-17 11:33:30.000000', NULL, 1),
(5198784, 754670, 62187, '<td valign="top">How could you go wrong with a smiling, pretty girl playing a guitar? I''d venture to say most DPC''ers will score this high.</td>', 'How could you go wrong with a smiling, pretty girl playing a guitar? I''d venture to say most DPC''ers will score this high.', '2009-01-17 11:37:42.000000', NULL, 1),
(5198789, 755307, 62187, '<td valign="top">I''ve never shot fish and I''m guessing you did this through glass. So, nice job I imagine and I certainly enjoy the colors in this one.</td>', 'I''ve never shot fish and I''m guessing you did this through glass. So, nice job I imagine and I certainly enjoy the colors in this one.', '2009-01-17 11:39:21.000000', NULL, 1),
(5198792, 755360, 62187, '<td valign="top">Brace yourself: clever title!</td>', 'Brace yourself: clever title!', '2009-01-17 11:40:32.000000', NULL, 1),
(5198800, 754987, 62187, '<td valign="top">It will get better as the day goes on...</td>', 'It will get better as the day goes on...', '2009-01-17 11:42:23.000000', NULL, 1),
(5198805, 753917, 62187, '<td valign="top">Excellent perspective but I wonder what the colored version was like. Very nice focus too!</td>', 'Excellent perspective but I wonder what the colored version was like. Very nice focus too!', '2009-01-17 11:43:59.000000', NULL, 1),
(5198836, 753615, 99412, '<td valign="top">That guy should be watching the dog. (He may be next)<br/>:)<br/>Nice capture.<br/>:)</td>', 'That guy should be watching the dog. (He may be next):)Nice capture.:)', '2009-01-17 12:00:39.000000', NULL, 1),
