(5198930, 755072, 99412, '<td valign="top">Looks to me as though you worked hard on this photo.<br/>10<br/>:)</td>', 'Looks to me as though you worked hard on this photo.10:)', '2009-01-17 12:22:29.000000', NULL, 1),
(5198996, 755226, 30982, '<td valign="top">One of my favorites for this challenge.  The lens flare is gorgeous.  Lovely depth, richness.  The different postures - youth, middle age, old age - perfect.</td>', 'One of my favorites for this challenge.  The lens flare is gorgeous.  Lovely depth, richness.  The different postures - youth, middle age, old age - perfect.', '2009-01-17 12:48:25.000000', NULL, 1),
(5198997, 754147, 30982, '<td valign="top">Very well seen and a very good "slice of life", quite literally.</td>', 'Very well seen and a very good "slice of life", quite literally.', '2009-01-17 12:48:41.000000', NULL, 1),
(5198999, 755364, 30982, '<td valign="top">Adorable, and nicely titled!  Great detail and tones, and did I mention adorable?</td>', 'Adorable, and nicely titled!  Great detail and tones, and did I mention adorable?', '2009-01-17 12:49:04.000000', NULL, 1),
(5199001, 753595, 30982, '<td valign="top">This is a wonderful lovely high-key soft pastel-in-gray photograph and just very pleasant to visit with.</td>', 'This is a wonderful lovely high-key soft pastel-in-gray photograph and just very pleasant to visit with.', '2009-01-17 12:50:01.000000', NULL, 1),
(5199003, 755325, 30982, '<td valign="top">You''ve got a spaceship full of aliens and a full moon - it doesn''t get any better than that!  Very well seen and quite good for this challenge as well.</td>', 'You''ve got a spaceship full of aliens and a full moon - it doesn''t get any better than that!  Very well seen and quite good for this challenge as well.', '2009-01-17 12:50:35.000000', NULL, 1),
(5199005, 755250, 30982, '<td valign="top">Those long shadows are just wonderful!</td>', 'Those long shadows are just wonderful!', '2009-01-17 12:51:03.000000', NULL, 1),
(5199008, 755198, 30982, '<td valign="top">Outstanding portrait!</td>', 'Outstanding portrait!', '2009-01-17 12:51:47.000000', NULL, 1),
(5199009, 755296, 30982, '<td valign="top">Definitely a wonderful glimpse at life.  Very enjoyable and looks to have been a great day!</td>', 'Definitely a wonderful glimpse at life.  Very enjoyable and looks to have been a great day!', '2009-01-17 12:52:22.000000', NULL, 1),
(5199010, 754283, 30982, '<td valign="top">Perfect composition and excellent detail to show off this creature.</td>', 'Perfect composition and excellent detail to show off this creature.', '2009-01-17 12:52:43.000000', NULL, 1),
(5199012, 755400, 30982, '<td valign="top">That is just entirely too cute.  Tugs right at the heartstrings!</td>', 'That is just entirely too cute.  Tugs right at the heartstrings!', '2009-01-17 12:53:00.000000', NULL, 1),
(5199014, 755336, 30982, '<td valign="top">I really really like this.  It may not be "tack sharp" and that''s totally fine by me - the softness works here.  And that look!  Very enjoyable photograph.</td>', 'I really really like this.  It may not be "tack sharp" and that''s totally fine by me - the softness works here.  And that look!  Very enjoyable photograph.', '2009-01-17 12:53:36.000000', NULL, 1),
(5199019, 754903, 30982, '<td valign="top">An excellent interpretation of the challenge in my opinion.  It will be too busy for some, yet the way you''ve captured and presented it makes it somewhat lonely despite all the structure around.  Conveys the message from your title very well.</td>', 'An excellent interpretation of the challenge in my opinion.  It will be too busy for some, yet the way you''ve captured and presented it makes it somewhat lonely despite all the structure around.  Conveys the message from your title very well.', '2009-01-17 12:54:56.000000', NULL, 1),
(5199022, 755274, 30982, '<td valign="top">Not something you see every day, now is it?  Or perhaps it is, on this beach.  At any rate, works very well for the challenge, is a great pic, and I appreciate you sharing this with us!</td>', 'Not something you see every day, now is it?  Or perhaps it is, on this beach.  At any rate, works very well for the challenge, is a great pic, and I appreciate you sharing this with us!', '2009-01-17 12:55:36.000000', NULL, 1),
(5199026, 755129, 30982, '<td valign="top">This is perfect!  Love the expression, the detail, the composition, the B&amp;W - all excellent!</td>', 'This is perfect!  Love the expression, the detail, the composition, the B&W - all excellent!', '2009-01-17 12:56:01.000000', NULL, 1),
(5199029, 753822, 30982, '<td valign="top">Makes me smile!  Great expression.</td>', 'Makes me smile!  Great expression.', '2009-01-17 12:56:18.000000', NULL, 1),
(5199032, 755259, 30982, '<td valign="top">It''s cheating a bit to use such adorable subjects, you know.  Those eyes, those curls!  And who doesn''t love an elephant robe!  Beautifully done.</td>', 'It''s cheating a bit to use such adorable subjects, you know.  Those eyes, those curls!  And who doesn''t love an elephant robe!  Beautifully done.', '2009-01-17 12:57:02.000000', NULL, 1),
(5199036, 755340, 30982, '<td valign="top">I really like this.  Very pleasing colors, excellent composition, WONDERFUL texture in the window, and that one bit reaching for the light - really suits the challenge well, and is a good picture on its own.  Nice work.</td>', 'I really like this.  Very pleasing colors, excellent composition, WONDERFUL texture in the window, and that one bit reaching for the light - really suits the challenge well, and is a good picture on its own.  Nice work.', '2009-01-17 12:57:55.000000', NULL, 1),
(5199037, 755352, 30982, '<td valign="top">You are very lucky - this is one fine looking youngun'' and looks to have an outstanding, sunny dispostion as well.  An excellent portrait on all counts.</td>', 'You are very lucky - this is one fine looking youngun'' and looks to have an outstanding, sunny dispostion as well.  An excellent portrait on all counts.', '2009-01-17 12:58:28.000000', NULL, 1),
(5199039, 754650, 30982, '<td valign="top">Wonderful.  I really like this.</td>', 'Wonderful.  I really like this.', '2009-01-17 12:58:42.000000', NULL, 1),
(5199043, 754772, 30982, '<td valign="top">Sweet portrait!  Excellent work with tones and keeping detail in both light and dark sections, and the catchlights in the eyes really make the shot.</td>', 'Sweet portrait!  Excellent work with tones and keeping detail in both light and dark sections, and the catchlights in the eyes really make the shot.', '2009-01-17 12:59:24.000000', NULL, 1),
(5199045, 755372, 30982, '<td valign="top">Fun!!  Lovely light, and wonderful how you caught the snow spray.</td>', 'Fun!!  Lovely light, and wonderful how you caught the snow spray.', '2009-01-17 12:59:40.000000', NULL, 1),
(5199048, 754670, 30982, '<td valign="top">Natural and warm - gotta love that smile!</td>', 'Natural and warm - gotta love that smile!', '2009-01-17 13:00:06.000000', NULL, 1),
(5199049, 755066, 30982, '<td valign="top">What a neat idea for the challenge, and for a photograph!</td>', 'What a neat idea for the challenge, and for a photograph!', '2009-01-17 13:00:33.000000', NULL, 1),
(5199051, 755051, 30982, '<td valign="top">Oh, how sweet!  I''m a sucker for cute cuddly critters and this one looks just as soft as can be.</td>', 'Oh, how sweet!  I''m a sucker for cute cuddly critters and this one looks just as soft as can be.', '2009-01-17 13:00:59.000000', NULL, 1),
(5199052, 755285, 30982, '<td valign="top">Heh!  Greeting card material!!</td>', 'Heh!  Greeting card material!!', '2009-01-17 13:01:08.000000', NULL, 1),
(5199054, 755356, 30982, '<td valign="top">This is great.  Excellent pose, all that curly fur... good job with the lighting, too.</td>', 'This is great.  Excellent pose, all that curly fur... good job with the lighting, too.', '2009-01-17 13:01:36.000000', NULL, 1),
(5199056, 754978, 30982, '<td valign="top">Your title indicates perhaps a sad place, but to me this is life-affirming.  Peaceful, even.  Very nicely captured - the light on the water is gorgeous.</td>', 'Your title indicates perhaps a sad place, but to me this is life-affirming.  Peaceful, even.  Very nicely captured - the light on the water is gorgeous.', '2009-01-17 13:02:25.000000', NULL, 1),
(5199057, 753917, 30982, '<td valign="top">Great interpretation of this challenge, from the viewpoint, to the toning (that touch of white left in the flower petals) to the light from "above".</td>', 'Great interpretation of this challenge, from the viewpoint, to the toning (that touch of white left in the flower petals) to the light from "above".', '2009-01-17 13:03:02.000000', NULL, 1),
(5199062, 754741, 30982, '<td valign="top">I really like this.  Perfect choice of DOF, particularly the OOF foreground feetsies, and love the light on the face, the ear on the pillow, the texture of the couch.  Excellent conversion, comp, etc.  Just an all around very enjoyable photograph!</td>', 'I really like this.  Perfect choice of DOF, particularly the OOF foreground feetsies, and love the light on the face, the ear on the pillow, the texture of the couch.  Excellent conversion, comp, etc.  Just an all around very enjoyable photograph!', '2009-01-17 13:04:11.000000', NULL, 1),
(5199064, 753422, 30982, '<td valign="top">Ah, yes, without even seeing your title, this spoke of joy to me.</td>', 'Ah, yes, without even seeing your title, this spoke of joy to me.', '2009-01-17 13:04:32.000000', NULL, 1),
(5199066, 755251, 30982, '<td valign="top">Lovely B&amp;W!!  Great DOF, clarity, and an excellent presentation for this challenge.</td>', 'Lovely B&W!!  Great DOF, clarity, and an excellent presentation for this challenge.', '2009-01-17 13:05:12.000000', NULL, 1),
(5199068, 754969, 30982, '<td valign="top">This really makes me smile!</td>', 'This really makes me smile!', '2009-01-17 13:05:41.000000', NULL, 1),
(5199073, 754789, 30982, '<td valign="top">What excellent detail and depth to the leaves here, and gorgeous color.  Beautiful handling of the light, exposure.</td>', 'What excellent detail and depth to the leaves here, and gorgeous color.  Beautiful handling of the light, exposure.', '2009-01-17 13:06:32.000000', NULL, 1),
(5199074, 754284, 30982, '<td valign="top">Vibrant and alive!  Lovely macro.</td>', 'Vibrant and alive!  Lovely macro.', '2009-01-17 13:06:45.000000', NULL, 1),
(5199075, 755222, 30982, '<td valign="top">Sweet - my kind of shot.</td>', 'Sweet - my kind of shot.', '2009-01-17 13:06:57.000000', NULL, 1),
(5199089, 754670, 52549, '<td valign="top">Fantastic shot. Love the b/w.</td>', 'Fantastic shot. Love the b/w.', '2009-01-17 13:11:50.000000', NULL, 1),
(5199091, 754825, 30982, '<td valign="top">A very fun slice of life picture!</td>', 'A very fun slice of life picture!', '2009-01-17 13:12:49.000000', NULL, 1),
(5199094, 755347, 30982, '<td valign="top">This has a rather sinister overtone to it, but the child''s reaction dispells that a bit.</td>', 'This has a rather sinister overtone to it, but the child''s reaction dispells that a bit.', '2009-01-17 13:13:23.000000', NULL, 1),
(5199096, 753352, 52549, '<td valign="top">Mildred is a real cutie. The pice of blanket on the right is a bit of a distraction.</td>', 'Mildred is a real cutie. The pice of blanket on the right is a bit of a distraction.', '2009-01-17 13:13:55.000000', NULL, 1),
(5199100, 754933, 52549, '<td valign="top">Very good. Beautiful golden colors.</td>', 'Very good. Beautiful golden colors.', '2009-01-17 13:14:52.000000', NULL, 1),
(5199104, 755370, 52549, '<td valign="top">My goodness. Never, ever seen anything like this. Stunning shot!</td>', 'My goodness. Never, ever seen anything like this. Stunning shot!', '2009-01-17 13:16:06.000000', NULL, 1),
(5199105, 754687, 52549, '<td valign="top">Oh Wow!! My favourite so far, love the sepie/golden toning.</td>', 'Oh Wow!! My favourite so far, love the sepie/golden toning.', '2009-01-17 13:17:00.000000', NULL, 1),
(5199108, 754426, 52549, '<td valign="top">The colors are good but the focus is off which spoils the otherwise pretty image.</td>', 'The colors are good but the focus is off which spoils the otherwise pretty image.', '2009-01-17 13:18:27.000000', NULL, 1),
(5199109, 754341, 52549, '<td valign="top">Wonderful clarity.</td>', 'Wonderful clarity.', '2009-01-17 13:19:33.000000', NULL, 1),
(5199113, 755386, 52549, '<td valign="top">Beautiful. Very aesthetic, wonderful colors and I love the reflection.</td>', 'Beautiful. Very aesthetic, wonderful colors and I love the reflection.', '2009-01-17 13:22:25.000000', NULL, 1),
(5199116, 754978, 52549, '<td valign="top">Not keen on the title but it''s a wonderful shot. Good luck.</td>', 'Not keen on the title but it''s a wonderful shot. Good luck.', '2009-01-17 13:25:06.000000', NULL, 1),
(5199117, 755126, 52549, '<td valign="top">This is really beautiful. The expression on the birds face (although I''m not sure if a bird can have an expression ;-) and the perspective are fantastic.</td>', 'This is really beautiful. The expression on the birds face (although I''m not sure if a bird can have an expression ;-) and the perspective are fantastic.', '2009-01-17 13:26:57.000000', NULL, 1),
(5199124, 755376, 52549, '<td valign="top">Lovely delicate composition.</td>', 'Lovely delicate composition.', '2009-01-17 13:29:56.000000', NULL, 1),
(5199125, 754631, 52549, '<td valign="top">Vibrant definitely describes this beautiful image. This should be top three. Good luck.</td>', 'Vibrant definitely describes this beautiful image. This should be top three. Good luck.', '2009-01-17 13:31:17.000000', NULL, 1),
(5199127, 755274, 70888, '<td valign="top">pretty much the wierdest thing ive seen today...nice shot</td>', 'pretty much the wierdest thing ive seen today...nice shot', '2009-01-17 13:32:36.000000', NULL, 1),
(5199130, 755347, 52549, '<td valign="top">Totally brilliant! Could this be MAK? We''ll see....</td>', 'Totally brilliant! Could this be MAK? We''ll see....', '2009-01-17 13:36:25.000000', NULL, 1),
(5199131, 755254, 52549, '<td valign="top">Wonderful composition and colors.</td>', 'Wonderful composition and colors.', '2009-01-17 13:37:04.000000', NULL, 1),
(5199132, 755349, 70888, '<td valign="top">cows on the shore,twice in one day,guess it occurs more than i thought,lol</td>', 'cows on the shore,twice in one day,guess it occurs more than i thought,lol', '2009-01-17 13:37:36.000000', NULL, 1),
(5199134, 754701, 52549, '<td valign="top">Simple and subtle. Wonderful!</td>', 'Simple and subtle. Wonderful!', '2009-01-17 13:38:30.000000', NULL, 1),
(5199136, 755272, 52549, '<td valign="top">Great title. Beautifully dynamic shot.</td>', 'Great title. Beautifully dynamic shot.', '2009-01-17 13:39:17.000000', NULL, 1),
