(5202859, 755199, 83313, '<td valign="top">A refreshing change from the usual portrait of a child smiling and laughing. This is just as frequent a behavior and fits the subject very well. It''s a part of life not frequently portrayed in portraits. I like how you''ve focused in on the teary eyes by the use of shallow DOF.</td>', 'A refreshing change from the usual portrait of a child smiling and laughing. This is just as frequent a behavior and fits the subject very well. It''s a part of life not frequently portrayed in portraits. I like how you''ve focused in on the teary eyes by the use of shallow DOF.', '2009-01-18 20:11:52.000000', NULL, 1),
(5202862, 754522, 83313, '<td valign="top">Interesting semi abstract. I''m not sure if this is a reflection, or upside down or what.</td>', 'Interesting semi abstract. I''m not sure if this is a reflection, or upside down or what.', '2009-01-18 20:12:28.000000', NULL, 1),
(5202871, 755271, 83313, '<td valign="top">Nice scene, but a bit grainy. There seems to be a pattern of some kind that is causing a problem. Mostly visible on the silo in the background.</td>', 'Nice scene, but a bit grainy. There seems to be a pattern of some kind that is causing a problem. Mostly visible on the silo in the background.', '2009-01-18 20:14:36.000000', NULL, 1),
(5202884, 754853, 83313, '<td valign="top">Looks like a sears catalog from the 70''s. Maybe fashion has come around again? I''m out of the loop.</td>', 'Looks like a sears catalog from the 70''s. Maybe fashion has come around again? I''m out of the loop.', '2009-01-18 20:16:40.000000', NULL, 1);
