INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5203665, 754478, 32345, '<td valign="top">Congrats for the red, it''s a great picture :)</td>', 'Congrats for the red, it''s a great picture :)', '2009-01-19 08:49:33.000000', NULL, 0),
(5203666, 754433, 32345, '<td valign="top">Congrats for your first ribbon and a new PB, way to go!!! :)</td>', 'Congrats for your first ribbon and a new PB, way to go!!! :)', '2009-01-19 08:50:36.000000', NULL, 0),
(5203668, 753615, 34192, '<td valign="top">Completely underrated.  This is one of those perfect juxtaposition moments when everything lines up and you couldn''t ask for a better scene in front of you to unfold.  Glad you were there so I could see it to.  This is what I love about photography.</td>', 'Completely underrated.  This is one of those perfect juxtaposition moments when everything lines up and you couldn''t ask for a better scene in front of you to unfold.  Glad you were there so I could see it to.  This is what I love about photography.', '2009-01-19 08:50:44.000000', NULL, 0),
(5203669, 755356, 32345, '<td valign="top">Congrats for a great finish and a new PB :)</td>', 'Congrats for a great finish and a new PB :)', '2009-01-19 08:51:25.000000', NULL, 0),
