(5203957, 754570, 67697, '<td valign="top">eww eww eww bug photos hehehe  Again - what an amazing photograph.  You rock!  Congrats on the blue!</td>', 'eww eww eww bug photos hehehe  Again - what an amazing photograph.  You rock!  Congrats on the blue!', '2009-01-19 10:29:34.000000', NULL, 0),
(5203960, 754433, 67697, '<td valign="top">Roz and Greg in the Top 3?  Conspiracy!!!! hehe  You two did wonderful.  And although I don''t like bugs, this is awesome. Congrats on the ribbon!</td>', 'Roz and Greg in the Top 3?  Conspiracy!!!! hehe  You two did wonderful.  And although I don''t like bugs, this is awesome. Congrats on the ribbon!', '2009-01-19 10:31:33.000000', NULL, 0),
(5203962, 754478, 67697, '<td valign="top">I wondered if this might be yours.  I loved the lighting and the clarity.  So beautiful!  Congrats on the ribbon!</td>', 'I wondered if this might be yours.  I loved the lighting and the clarity.  So beautiful!  Congrats on the ribbon!', '2009-01-19 10:32:25.000000', NULL, 0),
