(5205078, 753941, 3724, '<td valign="top">Pole acrobat - an interesting life figure study.  This appears to be minimal edit, in an exposure of complex lighting by a soft spot, also with mixed daylight/window &amp; ambient club light. A tight editorial crop denies the contribution of what may have proved to be life in an also interesting environment.</td>', 'Pole acrobat - an interesting life figure study.  This appears to be minimal edit, in an exposure of complex lighting by a soft spot, also with mixed daylight/window & ambient club light. A tight editorial crop denies the contribution of what may have proved to be life in an also interesting environment.', '2009-01-19 19:05:07.000000', NULL, 0),
(5205084, 754570, 54431, '<td valign="top">Congrats! I love macro bug shots! This one is fantastic! Amazing detail.</td>', 'Congrats! I love macro bug shots! This one is fantastic! Amazing detail.', '2009-01-19 19:08:23.000000', NULL, 0),
(5205088, 754478, 54431, '<td valign="top">Great capture! Congrats!</td>', 'Great capture! Congrats!', '2009-01-19 19:09:41.000000', NULL, 0),
