(5235445, 755347, 20577, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by heavyj:</b></div><hr/><i> This would have been so much better had you pulled the hoody off...I love the photo. </i></td></tr></table> <br/> <br/>Obviosuly this dude doesn''t know what you look like.</td>', 'Originally posted by heavyj: This would have been so much better had you pulled the hoody off...I love the photo.   Obviosuly this dude doesn''t know what you look like.', '2009-02-02 15:46:37.000000', NULL, 0),
(5236484, 754543, 30982, '<td valign="top">Lovely light, lovely mood to this, and I like the way you got her all in one little box.</td>', 'Lovely light, lovely mood to this, and I like the way you got her all in one little box.', '2009-02-03 00:24:03.000000', NULL, 0),
(5237271, 755362, 37444, '<td valign="top">Wonderful subject!</td>', 'Wonderful subject!', '2009-02-03 15:47:36.000000', NULL, 0),
(5237893, 754741, 30454, '<td valign="top">Excellent lighting, expressions, focus. Everything is perfect. Great job.</td>', 'Excellent lighting, expressions, focus. Everything is perfect. Great job.', '2009-02-03 22:14:33.000000', NULL, 0),
